function publishChatContext(){const guide=current();window.dispatchEvent(new CustomEvent("axon:context",{detail:{hospital:guide?{id:guide.id,name:guide.name,timezone:guide.timezone||""}:null,guidelineRows:guide?(guide.rows||[]).map(row=>({field:row.field,value:row.value,lastVerified:row.lastVerified||row.last_verified||""})):[],consultationTime:timeInput.value,encounterState:{...encounterState},lvoState,ctaState,thrombolyticState,orderPlacedState}}));}
