function render(){renderHospitalAvailability();[...lkwControls.querySelectorAll("button")].forEach(button=>button.classList.toggle("is-selected",button.dataset.lkw===lkwState));lkwTimeField.hidden=lkwState!=="Known";[...thrombolyticControls.querySelectorAll("button")].forEach(button=>button.classList.toggle("is-selected",button.dataset.thrombolytic===thrombolyticState));[...orderPlacedControls.querySelectorAll("button")].forEach(button=>button.classList.toggle("is-selected",button.dataset.orderPlaced===orderPlacedState));[...chargeControls.querySelectorAll("button")].forEach(button=>button.classList.toggle("is-selected",button.dataset.charge===(chargeEntered?"yes":"no")));[...planControls.querySelectorAll("button")].forEach(button=>button.classList.toggle("is-selected",button.dataset.plan===(planConfirmed?"yes":"no")));renderWorkflow();if(!current()){details.innerHTML="";validationList.innerHTML="";renderNudge();publishChatContext();return;}renderGuide();renderNudge();renderValidation();publishChatContext();}
function mergeGuides(incoming){const ids=new Set(incoming.map(item=>item.id));guides=[...guides.filter(item=>!ids.has(item.id)),...incoming];saveImports(guides);selectedId=incoming[0].id;timeOverridden=false;renderHospitals();setHospitalTime();render();}
function parseMap(text){const [headers,...rows]=parseCsv(text);return rows.map(row=>Object.fromEntries(headers.map((header,index)=>[header,row[index]||""])));}
function applyContext(context){selectedId=context.hospital_id;lvoState=context.field_event.field==="lvo_present"?(context.field_event.value?"yes":"no"):"";encounterState={...encounterState,intake:true,imaging:context.caselog_step==="Imaging"};timeInput.value=context.local_time.slice(0,16);timeOverridden=true;renderHospitals();hospitalSelect.value=selectedId;timeSource.textContent="Loaded from encounter context JSON.";render();}
async function importFiles(files){const messages=[],failures=[];for(const file of files){try{const text=await file.text();if(/\.json$/i.test(file.name)){const json=JSON.parse(text);if(isEncounterContext(json)){applyContext(json);messages.push("Loaded encounter context");}else if(Array.isArray(json)&&json[0]?.caselog_step&&json[0]?.caselog_field){fieldMap=json;messages.push("Loaded caselog map");}else if(Array.isArray(json)&&json[0]?.question&&json[0]?.expected_status){validationSet=json;renderValidation();messages.push("Loaded validation set");}else{const incoming=guidelinesFromJson(json,file.name);mergeGuides(incoming);messages.push("Imported "+incoming.length+" hospital guide"+(incoming.length>1?"s":""));}}else{const headers=parseCsv(text)[0]||[];if(headers.includes("caselog_step")&&headers.includes("caselog_field")){fieldMap=parseMap(text);messages.push("Loaded caselog map");}else if(headers.includes("expected_status")&&headers.includes("question")){validationSet=parseMap(text);renderValidation();messages.push("Loaded validation set");}else{mergeGuides([guidelineFromCsv(text,file.name,{imported:true})]);messages.push("Imported "+file.name);}}}catch(error){failures.push(file.name+": "+error.message);}}importStatus.textContent=[...messages,...failures].join(". ");}
async function importStoryboards(files){const messages=[],failures=[];for(const file of files){try{const text=await file.text(),rows=/\.json$/i.test(file.name)?JSON.parse(text):parseMap(text),incoming=normalizeStoryboardRows(Array.isArray(rows)?rows:rows.storyboard_notes||rows.storyboards,{imported:true});const key=row=>[normKey(row.hospital_id),normKey(row.field),normKey(row.consult_type),normKey(row.trigger)].join("|");const existing=new Map(storyboards.map(row=>[key(row),row]));incoming.forEach(row=>existing.set(key(row),row));storyboards=[...existing.values()];saveStoryboards();messages.push("Loaded "+incoming.length+" storyboard override"+(incoming.length===1?"":"s"));}catch(error){failures.push(file.name+": "+error.message);}}storyboardStatus.textContent=[...messages,...failures].join(". ");render();}
async function loadReference(){const [guideData,map,validations,storyboard]=await Promise.all([fetch("reference/hospital_guides.json").then(r=>r.json()),fetch("reference/caselog_field_map.csv").then(r=>r.text()),fetch("reference/validation_set.csv").then(r=>r.text()),fetch("reference/storyboard_notes.json").then(r=>r.json())]);guides=[...guidelinesFromJson(guideData,"hospital_guides.json").map(guide=>({...guide,imported:false})),...savedImports()];fieldMap=parseMap(map);validationSet=parseMap(validations);storyboards=[...normalizeStoryboardRows(storyboard),...storyboardStorage()];renderHospitals();setHospitalTime();render();importStatus.textContent="Ready — drop a CSV or JSON guide, or choose files.";storyboardStatus.textContent="Ready — import storyboard notes to apply nudge overrides.";}
hospitalSelect.addEventListener("change",()=>{selectedId=hospitalSelect.value;roundingHospital.value=selectedId;activeBackendNudge=null;timeOverridden=false;setHospitalTime();render();renderRounding();fireBackendNudge("Intake","encounter","opened");});roundingHospital.addEventListener("change",()=>{selectedId=roundingHospital.value;hospitalSelect.value=selectedId;renderRounding();});viewToggle.addEventListener("click",event=>{const view=event.target.dataset.view;if(!view)return;const isRounding=view==="rounding";consultView.hidden=isRounding;consultNudge.hidden=isRounding;roundingView.hidden=!isRounding;[...viewToggle.querySelectorAll("button")].forEach(button=>button.classList.toggle("is-selected",button.dataset.view===view));if(isRounding)renderRounding();});timeInput.addEventListener("input",()=>{timeOverridden=true;timeSource.textContent="Manual time override.";updateLastKnownWellElapsed();renderHospitalAvailability();});consultType.addEventListener("change",()=>{activeBackendNudge=null;render();fireBackendNudge(consultType.value==="Rounding"?"Rounding":"Intake","encounter","opened");});lkwControls.addEventListener("click",event=>{const state=event.target.dataset.lkw;if(!state)return;lkwState=state;render();fireBackendNudge("History","last_known_well",state);});thrombolyticControls.addEventListener("click",event=>{const state=event.target.dataset.thrombolytic;if(!state)return;thrombolyticState=state;activeBackendNudge=null;render();if(state==="yes")fireBackendNudge("Recommendation","thrombolytic_given",true);});orderPlacedControls.addEventListener("click",event=>{const state=event.target.dataset.orderPlaced;if(!state)return;orderPlacedState=state;activeBackendNudge=null;render();if(state==="yes")fireBackendNudge("Recommendation","order_field_displayed",true);});chargeControls.addEventListener("click",event=>{const state=event.target.dataset.charge;if(!state)return;chargeEntered=state==="yes";activeBackendNudge=null;render();});planControls.addEventListener("click",event=>{const state=event.target.dataset.plan;if(!state)return;planConfirmed=state==="yes";activeBackendNudge=null;render();});allergiesInput.addEventListener("change",()=>fireBackendNudge("History","allergies",allergiesInput.value));assessmentInput.addEventListener("change",()=>fireBackendNudge("Recommendation","assessment",assessmentInput.value));workflowState.addEventListener("click",event=>{const lvo=event.target.dataset.lvo,cta=event.target.dataset.cta;if(lvo){lvoState=lvo;activeBackendNudge=null;render();if(lvo==="yes")fireBackendNudge("Imaging","lvo_present",true);return;}if(cta){ctaState=cta;activeBackendNudge=null;render();fireBackendNudge("Imaging","cta_done",cta==="yes");return;}const button=event.target.closest("button[data-step]");if(!button)return;const key=button.dataset.step;encounterState[key]=!encounterState[key];activeBackendNudge=null;render();if(key==="signoff"&&encounterState[key])fireBackendNudge("Sign-off","complete_clicked",true);});fileInput.addEventListener("change",event=>importFiles([...event.target.files]));["dragenter","dragover"].forEach(type=>dropZone.addEventListener(type,event=>{event.preventDefault();dropZone.classList.add("is-dragging");}));["dragleave","drop"].forEach(type=>dropZone.addEventListener(type,event=>{event.preventDefault();dropZone.classList.remove("is-dragging");}));dropZone.addEventListener("drop",event=>importFiles([...event.dataTransfer.files].filter(file=>/\.(csv|json)$/i.test(file.name))));loadReference().catch(error=>importStatus.textContent="Unable to load bundled reference data: "+error.message);


storyboardInput.addEventListener("change",event=>importStoryboards([...event.target.files]));
["dragenter","dragover"].forEach(type=>storyboardDropZone.addEventListener(type,event=>{event.preventDefault();storyboardDropZone.classList.add("is-dragging");}));
["dragleave","drop"].forEach(type=>storyboardDropZone.addEventListener(type,event=>{event.preventDefault();storyboardDropZone.classList.remove("is-dragging");}));
storyboardDropZone.addEventListener("drop",event=>{event.preventDefault();importStoryboards([...event.dataTransfer.files].filter(file=>/\.(csv|json)$/i.test(file.name)));});

// Handbook-alignment layer: preserve both sources, make operational status explicit,
// and keep imported hospitals usable by the deterministic nudge service.
const nudgeStatus=$("#nudge-status"),infoPanel=$("#info-panel"),infoList=$("#info-list"),guidanceHealth=$("#guidance-health"),auditSummary=$("#audit-summary"),runValidationButton=$("#run-validation"),validationStatus=$("#validation-status");
let infoNudges=[];
function signoffRequirements(){const guide=current(),charge=field(guide,"Charge Entry"),completion=field(guide,"Consult Completion Rule");return {charge:/require|must|yes/i.test(charge),plan:/confirm|require|must/i.test(completion)};}
function audit(event,status,source=""){try{const key="axon-guidance-audit",items=JSON.parse(localStorage.getItem(key)||"[]"),entry={at:new Date().toISOString(),hospital:selectedId,event,status,source};items.unshift(entry);localStorage.setItem(key,JSON.stringify(items.slice(0,200)));auditSummary.textContent=`${items.length+1} guidance event${items.length?"s":""} recorded locally in this browser.`;}catch{auditSummary.textContent="Guidance was shown; browser audit storage is unavailable.";}}
function storyboardConflictFor(nudge){const guide=current();if(!guide||!nudge)return null;const sourceFields=(nudge.sources||[]).map(source=>normKey(source.field));return storyboards.find(note=>normKey(note.hospital_id)===normKey(guide.id)&&sourceFields.includes(normKey(note.field))&&normKey(field(guide,note.field))!==normKey(note.storyboard_value))||null;}
function statusLabel(nudge,conflict){const labels=[];if(conflict||nudge.status==="conflict"||nudge.flags?.includes("conflict"))labels.push("Conflict");else labels.push((nudge.status||"answered").replace(/_/g," "));if(nudge.flags?.includes("stale"))labels.push("Possibly out of date");if(nudge.tier==="hard_stop"&&!labels.includes("Hard stop"))labels.push("Hard stop");return labels.join(" · ");}
function backendNudgeToCard(nudge){const conflict=storyboardConflictFor(nudge),details=[...new Set(nudge.details||[])],sources=(nudge.sources||[]).map(source=>((current()?.name||source.hospital_id)+(source.hospital_id?" ("+source.hospital_id+")":"")+(source.field?" · "+source.field:"")).trim()).filter(Boolean);if(conflict){details.unshift(`Storyboard source: ${conflict.storyboard_value}${conflict.storyboard_updated?" (updated "+conflict.storyboard_updated+")":""}. ${conflict.note||""}`);details.unshift(`Guide source: ${field(current(),conflict.field)}.`);}if(nudge.why)details.push("Why this appeared: "+nudge.why);if(sources.length)details.push("Guide source: "+sources.join("; "));return {title:nudge.title,copy:conflict?`${conflict.field}: sources disagree. Review both values before proceeding.`:nudge.message,steps:details,source:conflict?"Conflict · guide and storyboard":(nudge.tier||"info").replace(/_/g," ")+" nudge",status:statusLabel(nudge,conflict)};}
function applyNudge(card){$("#nudge-heading").textContent=card.title;$("#nudge-copy").textContent=card.copy;$("#nudge-steps").innerHTML=card.steps.map(step=>"<li>"+escapeHtml(step)+"</li>").join("");$("#nudge-source").textContent=card.source;nudgeStatus.textContent=card.status||"";nudgeStatus.hidden=!card.status;}
function renderInfoNudges(){infoList.innerHTML=infoNudges.map(nudge=>{const card=backendNudgeToCard(nudge);return `<article><strong>${escapeHtml(card.title)} · ${escapeHtml(card.status)}</strong><p>${escapeHtml(card.copy)}</p><small>${escapeHtml(card.source)}</small></article>`;}).join("");infoPanel.hidden=!infoNudges.length;}
function renderNudge(){const req=signoffRequirements(),workflowComplete=["intake","history","clinicalWorkup","imaging","recommendation","note"].every(key=>encounterState[key]);if(workflowComplete&&((req.charge&&!chargeEntered)||(req.plan&&!planConfirmed))){consultNudge.hidden=false;applyNudge({title:"Sign-off blocked",copy:"Complete the hospital-required sign-off checks before closing this consult.",steps:[req.charge&&!chargeEntered?"Charge entry is required by this hospital guide.":"",req.plan&&!planConfirmed?"Plan confirmation is required by this hospital guide.":""].filter(Boolean),source:"Guide-driven sign-off check",status:"Hard stop"});return;}if(!activeBackendNudge){consultNudge.hidden=true;renderInfoNudges();return;}consultNudge.hidden=false;applyNudge(backendNudgeToCard(activeBackendNudge));renderInfoNudges();}
async function fireBackendNudge(caselogStep,fieldEvent,value){const base=nudgeApiBase(),guide=current();if(!base||!guide||!consultType.value||!timeInput.value)return;const requestId=++backendRequestId;guidanceHealth.textContent="Checking hospital guidance…";try{const response=await fetch(base+"/nudges",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({hospital_id:guide.id,consult_type:consultType.value,encounter_type:consultType.value==="Rounding"?"Rounding":"Acute",caselog_step:caselogStep,field_event:{field:fieldEvent,value},local_time:timeInput.value,local_timezone:guide.timezone||"",provider_timezone:Intl.DateTimeFormat().resolvedOptions().timeZone,charge_entered:chargeEntered,plan_confirmed:planConfirmed})});if(!response.ok)throw new Error("Nudge API request failed");const data=await response.json();if(requestId!==backendRequestId)return;const nudges=data.nudges||[];infoNudges=nudges.filter(nudge=>nudge.tier==="info");activeBackendNudge=nudges.filter(nudge=>nudge.tier==="hard_stop"||nudge.tier==="advisory").sort((a,b)=>({hard_stop:0,advisory:1}[a.tier]??2)-({hard_stop:0,advisory:1}[b.tier]??2))[0]||null;if(activeBackendNudge?.tier==="hard_stop"){encounterState.signoff=false;renderWorkflow();}guidanceHealth.textContent="Guidance ready · deterministic rule response in "+(data.ms??"<500")+" ms.";audit(fieldEvent,activeBackendNudge?.status||infoNudges[0]?.status||"silent",activeBackendNudge?.sources?.[0]?.field||infoNudges[0]?.sources?.[0]?.field||"");renderNudge();}catch{if(requestId===backendRequestId){activeBackendNudge=null;infoNudges=[];guidanceHealth.textContent="Guidance unavailable — the caselog remains usable; verify locally.";audit(fieldEvent,"guidance unavailable");renderNudge();}}}
function guidePayload(guide){return {hospitals:[{hospital_id:guide.id,hospital_name:guide.name,local_timezone:guide.timezone,fields:guide.rows.map(row=>({field:row.field,value:row.value,last_verified:row.lastVerified||row.last_verified||""}))}]};}
async function syncGuideToBackend(guide){const base=nudgeApiBase();if(!base||!guide?.imported)return;try{const response=await fetch(base+"/hospitals",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify(guidePayload(guide))});if(!response.ok)throw new Error();guidanceHealth.textContent="Imported hospital guide is ready for deterministic nudges.";}catch{guidanceHealth.textContent="Imported guide is available on-screen; live nudge service could not be updated.";}}
function mergeGuides(incoming){const ids=new Set(incoming.map(item=>item.id));guides=[...guides.filter(item=>!ids.has(item.id)),...incoming];saveImports(guides);selectedId=incoming[0].id;timeOverridden=false;renderHospitals();setHospitalTime();incoming.forEach(syncGuideToBackend);render();}
function parseValidationTime(value){const match=String(value||"").match(/(\d{4}-\d{2}-\d{2}).*?(\d{1,2}):(\d{2})/);return match?`${match[1]}T${match[2].padStart(2,"0")}:${match[3]}`:timeInput.value;}
async function runValidation(){const base=nudgeApiBase();if(!base){validationStatus.textContent="Validation needs the nudge service URL.";return;}runValidationButton.disabled=true;validationStatus.textContent="Running loaded validation questions…";let pass=0,done=0;for(const row of validationSet){try{const response=await fetch(base+"/ask",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({hospital_id:row.hospital_id,question:row.question,local_time:parseValidationTime(row.encounter_local_time),provider_timezone:Intl.DateTimeFormat().resolvedOptions().timeZone})});const data=await response.json();row._result=data.status||"error";row._pass=row._result===row.expected_status;pass+=row._pass?1:0;done++;}catch{row._result="error";row._pass=false;done++;}}validationStatus.textContent=`${pass}/${done} deterministic question checks passed.`;renderValidation();runValidationButton.disabled=false;}
runValidationButton.addEventListener("click",runValidation);
const signoffGateObserver=new MutationObserver(()=>{const button=workflowState.querySelector('[data-step="signoff"]');if(!button)return;const req=signoffRequirements(),stepsReady=["intake","history","clinicalWorkup","imaging","recommendation","note"].every(key=>encounterState[key]);const ready=stepsReady&&(!req.charge||chargeEntered)&&(!req.plan||planConfirmed);button.disabled=!ready;button.setAttribute("aria-disabled",String(!ready));const hint=button.querySelector("small");if(hint)hint.textContent=ready?"Complete safely.":"Complete earlier steps and this hospital's required sign-off checks.";});signoffGateObserver.observe(workflowState,{childList:true,subtree:true});
